 const totalSales=rows.reduce((s,r)=>s+r.sales,0),totalQty=rows.reduce((s,r)=>s+r.quantity,0),totalProfit=rows.reduce((s,r)=>s+r.profit,0),totalStock=rows.reduce((s,r)=>s+r.stockValue,0);rows=rows.map(r=>({...r,salesPct:pct(r.sales,totalSales),unitsPct:pct(r.quantity,totalQty),profitPct:pct(r.profit,totalProfit),inventoryValuePct:pct(r.stockValue,totalStock)}));
