async function pnlPeriod(businessId:string,from:Date,to:Date){const [txns,docs]=await Promise.all([db.accountTransaction.findMany({where:{businessId,transactionDate:{gte:from,lte:to}},include:{account:true}}),db.salesDocument.findMany({where:{businessId,documentType:"INVOICE",createdAt:{gte:from,lte:to},status:{notIn:INVALID_SALE_STATUSES}},select:{discount:true,returnedAmount:true}})]);let netRevenue=0,cogs=0,operatingExpenses=0,otherIncome=0,otherExpenses=0;for(const t of txns){const a=t.account||{},type=text(a.type).toLowerCase(),system=text(json(a.metadata).systemCode).toLowerCase(),amount=Number(t.amount||0),signedIncome=text(t.type).toLowerCase()==="credit"?amount:-amount,signedExpense=text(t.type).toLowerCase()==="debit"?amount:-amount;if(type==="income"){if(system.includes("other"))otherIncome+=signedIncome;else netRevenue+=signedIncome;}else if(type==="cogs")cogs+=signedExpense;else if(type==="expense"){if(system.includes("other"))otherExpenses+=signedExpense;else operatingExpenses+=signedExpense;}}const discounts=docs.reduce((s:number,d:any)=>s+Number(d.discount||0),0),returns=docs.reduce((s:number,d:any)=>s+Number(d.returnedAmount||0),0),contra=discounts+returns,revenue=netRevenue+contra,grossProfit=netRevenue-cogs,operatingProfit=grossProfit-operatingExpenses,netProfit=operatingProfit+otherIncome-otherExpenses;return{revenue,contra,netRevenue,cogs,grossProfit,operatingExpenses,operatingProfit,otherIncome,otherExpenses,netProfit};}
async function pnlReport(businessId:string,q:any){const range=presetRange(q),compare=comparisonRange(range.from,range.to);const [cur,prev]=await Promise.all([pnlPeriod(businessId,range.from,range.to),pnlPeriod(businessId,compare.from,compare.to)]);const lines:[string,keyof typeof cur][]=[["Revenue","revenue"],["Less: Sales Returns / Discounts","contra"],["Net Revenue","netRevenue"],["Cost of Goods Sold","cogs"],["Gross Profit","grossProfit"],["Operating Expenses","operatingExpenses"],["Operating Profit","operatingProfit"],["Other Income","otherIncome"],["Other Expenses","otherExpenses"],["Net Profit","netProfit"]];const rows=lines.map(([label,key])=>{const amount=money(cur[key]),comparisonAmount=money(prev[key]),difference=money(amount-comparisonAmount);return{line:label,amount,comparisonAmount,difference,changePct:pct(difference,Math.abs(comparisonAmount)),revenuePct:pct(amount,cur.netRevenue||cur.revenue)}});return finalize("Profit & Loss",[{key:"line",label:"P&L Line"},{key:"amount",label:"Amount"},{key:"comparisonAmount",label:"Comparison Period"},{key:"difference",label:"Difference"},{key:"changePct",label:"% Change"},{key:"revenuePct",label:"% of Revenue"}],rows,[{label:"Net Revenue",value:money(cur.netRevenue)},{label:"Gross Profit",value:money(cur.grossProfit)},{label:"Operating Profit",value:money(cur.operatingProfit)},{label:"Net Profit",value:money(cur.netProfit)},{label:"Net Margin %",value:pct(cur.netProfit,cur.netRevenue),format:"percent"}],q,{period:range.preset,from:range.from,to:range.to,comparisonFrom:compare.from,comparisonTo:compare.to,accountingBasis:"accrual-ledger"});}

export function isGrocery21To30Report(id:string){return IDS.has(id);}
export function grocery21To30Catalog(){return GROCERY_21_30_REPORTS;}
export async function runGrocery21To30Report(businessId:string,id:string,q:any={}){if(!IDS.has(id))throw new ApiError(404,"Grocery report not found");await requireGrocery(businessId);const family=GROCERY_21_30_REPORTS.find(x=>x.id===id)?.family;if(family==="sales")return salesReport(businessId,id,q);if(family==="product")return productReport(businessId,id,q);if(family==="customer")return customerReport(businessId,id,q);if(family==="payment")return paymentReport(businessId,id,q);if(family==="purchase")return purchaseReport(businessId,id,q);if(family==="inventory")return inventoryReport(businessId,id,q);return pnlReport(businessId,q);}
